arguments.command:
python3 -c "
from openpyxl import load_workbook
wb = load_workbook('budget.xlsx')
for ws in wb.worksheets:
    print(f'Sheet: {ws.title}, dims: {ws.dimensions}, max_row: {ws.max_row}, max_col: {ws.max_column}')
    for row in ws.iter_rows(min_row=1, max_row=ws.max_row, max_col=3):
        for cell in row:
            if cell.value is not None:
                print(f'{cell.coordinate}: {repr(cell.value)}')
"
